\section*{অধ্যায় 8}
\textbf{মানব শারীরতত্ত্ব: রক্ত ও রক্ত সংবহন}
(HUMAN PHYSIOLOGY: BLOOD AND CIRCULATION)

\begin{figure}[h]
    \centering
    \includegraphics[width=0.4\textwidth]{blood_cells.png}
    \caption{Blood cells}
\end{figure}

\begin{figure}[h]
    \centering
    \includegraphics[width=0.4\textwidth]{heart_diagram.png}
    \caption{Heart diagram}
\end{figure}

আমাদের দেহের ভেতর একটি বিশেষ তন্ত্র খাদ্যসার, শ্বসন গ্যাস ও রেচন বজ্রা পরিবহন এবং দেহের তাপমাত্রা নিয়ন্ত্রণ, বিপাক ক্রিয়া নিয়ন্ত্রণ, বিভিন্ন অঙ্গ ও তন্ত্রের মধ্যে সমন্বয় সাধন ও রোগজীবাণু প্রতিরোধ কাজে সক্রিয়ভাবে নিয়োজিত। বৃত্তিশ বিজ্ঞানী উইলিয়াম হার্ভে (William Harvey) 1628 সালে সর্বপ্রথম মানবদেহে এ ধরনের একটি তন্ত্রের বৈজ্ঞানিক পরিকল্পনা প্রকাশ করেন। এর নাম রক্ত সংবহনতন্ত্র। এ অধ্যায়ে মানব রক্ত সংবহনতন্ত্র এবং এর কিছু জটিলতা নিয়ে আলোচনা করা হয়েছে।

\textbf{প্রধান শব্দাবলি (Key words)}
\begin{itemize}[noitemsep]
    \item রক্ত
    \item প্লাজমা
    \item হৃৎক্রি
    \item কার্ডিয়াক পেশি
    \item ব্যারোরিসেন্টর
    \item সিস্টেমিক সংবহন
    \item করোনারি বাইপাস
    \item লসিকা
    \item রক্ততন্ত্র
    \item অ্যানজাইনা
    \item হার্ট অ্যাটাক
    \item হার্ট ফেইলিউর
    \item পেস মেকার
    \item অ্যানজিওপ্লাস্টি
\end{itemize}

\textbf{পিরিয়ড সংখ্যা 14} এ অধ্যায় পাঠ শেষে শিক্ষার্থীরা যা পারবে

\begin{tabularx}{\textwidth}{|X|X|}
\hline
\textbf{নিখনফল} & \textbf{বিষয়বস্তু} \\
\hline
1. রক্ত কণিকা ও লসিকা সম্পর্কে বর্ণনা করতে পারবে। & \textbullet রক্ত ও লসিকা \\
2. রক্ত জমাট বাধার ব্যাখ্যা করতে পারবে। & \textbullet রক্ত জমাট বাধা \\
3. ব্যবহারিক: রক্তের কণিকাসমূহ শনাক্ত ও চিত্র অঙ্কন করতে পারবে। & \textbullet ব্যবহারিক \\
4. হৃৎপিণ্ডের গঠন বর্ণনা করতে পারবে। & \textbullet রক্ত কণিকাসমূহের স্থায়ী স্লুইড পর্যায়ক্রম \\
5. হার্টবিটের দশাসমূহ ব্যাখ্যা করতে পারবে। & \textbullet হৃৎপিণ্ডের গঠন \\
6. হার্টবিট নিয়ন্ত্রণে SA নোড, AV নোড এবং পারকিনজি আঁশের (Purkinji fibers) ভূমিকা ব্যাখ্যা করতে পারবে। & \textbullet হার্টবিট, বিভিন্ন দশা ও এর নিয়ন্ত্রণে SA নোড, AV নোড এবং পারকিনজি আঁশের ভূমিকা \\
7. রক্তচাপ নিয়ন্ত্রণে ব্যারোরিসেন্টর (baroreceptors) এবং আয়তন & \textbullet রক্তচাপ নিয়ন্ত্রণে ব্যারোরিসেন্টর এবং আয়তন \\
\hline
\end{tabularx}

\end{document}

