\section{অন্তর্বৃত্তিক প্রশ্ন (পুনরা)}
\subsection{নিচের উদ্ধৃতিটি থেকে ১৯ ও ২০ নং প্রশ্নের উত্তর দাওঃ-}
মানুষের হর্ষপিঙ্গ থেকে মহাধমনির মাধ্যমে O₂ যুক্ত রক্ত দেহের বিভিন্ন অঙ্গে যায় এবং CO₂ যুক্ত রক্ত মহাশিরার মাধ্যমে হর্ষপিঙ্গ ফিরে আসে। এজন্য হর্ষপিঙ্গে সজীব পাম্পায় বলা হয়।

\begin{enumerate}[label=\arabic*.]
    \item উদ্ধৃতিকে বর্ণিত ধমনি হর্ষপিঙ্গের কোন প্রকৌষ্ট থেকে উৎপত্তি লাভ করে?
        \begin{enumerate}[label=(\alph*)]
            \item ডান অ্যাট্রিয়াম
            \item বাম অ্যাট্রিয়াম
        \end{enumerate}
    \item উদ্ধৃতিকে উল্লেখিত পাম্পায়ন্ত্রির পেশিতে রক্ত সংগ্রহলক্ষে কোন ধরনের রক্ত সংবহনতন্ত্র বলে?
        \begin{enumerate}[label=(\alph*)]
            \item সিস্টেমিক
            \item করোনারি
        \end{enumerate}
\end{enumerate}

\subsection{নিচের উদ্ধৃতিটি পড় এবং ২১ ও ২২ নং প্রশ্নের উত্তর দাওঃ-}
টাই-কাসপিড ও বাই-কাসপিড কপাটিকা বক্ষের কারণে নিলয় থেকে রক্ত যথাক্রমে পালমোনারি ও সিস্টেমিক মহাধমনিতে যায়।

\begin{enumerate}[label=\arabic*.]
    \item উদ্ধৃতিকে উল্লিখিত ঘটনাটির ক্ষেত্রে নিচের কোনটি সত্যিক?
        \begin{enumerate}[label=(\alph*)]
            \item অলিন্দের ডায়াস্টেল
            \item অলিন্দের সিস্টেল
        \end{enumerate}
    \item উদ্ধৃতিকে উল্লিখিত কপাটিকা দুটি বক্ষ থাকে যে ধাপে-(i) অলিন্দের সিস্টেল (ii) অলিন্দের ডায়াস্টেল (iii) নিলয়ের সিস্টেল
\end{enumerate}

